function renderBackgroundLayersLegacyA(ctx: UIContext, layers: readonly BackgroundLayerDef[], active: boolean): string {
  const entries = [{ id: 'system-color-background', system: true as const, index: -1 }, ...layers.map((layer, index) => ({ id: layer.id ?? `user-background-${index}`, system: false as const, index }))];
  const rank = new Map(backgroundLayerOrderForRender.map((id, index) => [id, index]));
  entries.sort((a, b) => (rank.get(a.id) ?? Number.MAX_SAFE_INTEGER) - (rank.get(b.id) ?? Number.MAX_SAFE_INTEGER));
  const systemIndex = entries.findIndex(entry => entry.system);
  const systemLayer = `<fieldset class="user-theme-component user-theme-background-layer user-theme-system-layer"><legend>系统颜色层</legend><small>由颜色系统根据主题色自动生成背景渐变；不可移除，可通过系统颜色层开关忽略。</small><div class="user-theme-layer-meta"><span>来源：主题色系统</span><span>状态：固定层</span></div><div class="user-theme-layer-order"><button type="button" class="user-theme-token-clear" data-user-theme-system-layer-move="up" ${active && systemIndex > 0 ? '' : 'disabled'}>上移</button><button type="button" class="user-theme-token-clear" data-user-theme-system-layer-move="down" ${active && systemIndex < entries.length - 1 ? '' : 'disabled'}>下移</button></div></fieldset>`;
  const userLayerCount = entries.length - 1;
  const userLayers = entries.filter(entry => !entry.system).map((entry, position) => {
    const layer = layers[entry.index];
    if (!layer) return '';
    return `<fieldset class="user-theme-component user-theme-background-layer"><legend>${ctx.escapeHtml(layer.id ?? `表现层 ${entry.index + 1}`)}</legend><label class="user-theme-field"><span>表现类型</span><select data-user-theme-background-field="kind" data-user-theme-background-index="${entry.index}" ${active ? '' : 'disabled'}><option value="solid" ${layer.kind === 'solid' ? 'selected' : ''}>纯色</option><option value="gradient" ${layer.kind === 'gradient' ? 'selected' : ''}>渐变</option><option value="image" ${layer.kind === 'image' ? 'selected' : ''}>图片资源</option></select></label><label class="user-theme-field"><span>表现层 ID</span><input type="text" data-user-theme-background-field="id" data-user-theme-background-index="${entry.index}" value="${ctx.escapeHtml(layer.id ?? '')}" ${active ? '' : 'disabled'}></label><label class="user-theme-field"><span>值 / 图片资源引用</span><input type="text" data-user-theme-background-field="value" data-user-theme-background-index="${entry.index}" value="${ctx.escapeHtml(layer.value)}" ${active ? '' : 'disabled'}></label><div class="user-theme-number-row"><label>透明度 <input type="number" min="0" max="1" step="0.05" data-user-theme-background-field="opacity" data-user-theme-background-index="${entry.index}" value="${layer.opacity ?? 1}" ${active ? '' : 'disabled'}></label><label>附着 <select data-user-theme-background-field="attachment" data-user-theme-background-index="${entry.index}" ${active ? '' : 'disabled'}>${(['scroll', 'fixed', 'local'] as const).map(value => `<option value="${value}" ${layer.attachment === value ? 'selected' : ''}>${value === 'scroll' ? '滚动' : value === 'fixed' ? '固定' : '局部'}</option>`).join('')}</select></label></div><div class="user-theme-number-row"><label>定位 <input type="text" data-user-theme-background-field="position" data-user-theme-background-index="${entry.index}" value="${ctx.escapeHtml(layer.position ?? 'center')}" ${active ? '' : 'disabled'}></label><label>尺寸 <input type="text" data-user-theme-background-field="size" data-user-theme-background-index="${entry.index}" value="${ctx.escapeHtml(layer.size ?? 'cover')}" ${active ? '' : 'disabled'}></label></div><div class="user-theme-number-row"><label>重复 <select data-user-theme-background-field="repeat" data-user-theme-background-index="${entry.index}" ${active ? '' : 'disabled'}>${(['repeat', 'repeat-x', 'repeat-y', 'no-repeat', 'space', 'round'] as const).map(value => `<option value="${value}" ${layer.repeat === value ? 'selected' : ''}>${value}</option>`).join('')}</select></label><label>混合 <select data-user-theme-background-field="blendMode" data-user-theme-background-index="${entry.index}" ${active ? '' : 'disabled'}>${(['normal', 'multiply', 'screen', 'overlay', 'soft-light', 'hard-light', 'darken', 'lighten'] as const).map(value => `<option value="${value}" ${layer.blendMode === value ? 'selected' : ''}>${value}</option>`).join('')}</select></label></div><div class="user-theme-layer-order"><button type="button" class="user-theme-token-clear" data-user-theme-background-move="${entry.index}" data-direction="up" ${active && position > 0 ? '' : 'disabled'}>上移</button><button type="button" class="user-theme-token-clear" data-user-theme-background-move="${entry.index}" data-direction="down" ${active && position < userLayerCount - 1 ? '' : 'disabled'}>下移</button><button type="button" class="user-theme-token-clear" data-user-theme-background-remove="${entry.index}" ${active ? '' : 'disabled'}>移除表现层</button></div></fieldset>`;
  });
  const rendered = entries.map((entry, index) => entry.system ? systemLayer : userLayers.shift() ?? '').join('');
  return rendered;
}
